MODELS = ("product", "productcategory", "productmedia", "pricelist", "pricelistitem")
# the modules whose Entities use the catalogue today
CONSUMERS = ("inventory", "sales", "purchases", "farmacia")


def move_content_types(apps, schema_editor):
    ContentType = apps.get_model("contenttypes", "ContentType")
    for model in MODELS:
        if ContentType.objects.filter(app_label="catalog", model=model).exists():
            continue
        ContentType.objects.filter(app_label="inventory", model=model).update(app_label="catalog")


def restore_content_types(apps, schema_editor):
    ContentType = apps.get_model("contenttypes", "ContentType")
    for model in MODELS:
        if not ContentType.objects.filter(app_label="inventory", model=model).exists():
            ContentType.objects.filter(app_label="catalog", model=model).update(app_label="inventory")


def activate_catalog(apps, schema_editor):
    App = apps.get_model("django_resaas", "App")
    EntityApp = apps.get_model("django_resaas", "EntityApp")
    EntityTypeApp = apps.get_model("django_resaas", "EntityTypeApp")

    users = EntityApp.objects.filter(app__name__in=CONSUMERS, state="Active").select_related("entity")
    if not users.exists():
        return
    catalog, _ = App.objects.get_or_create(name="catalog", defaults={"state": "Active"})
    for row in users:
        EntityApp.objects.get_or_create(entity_id=row.entity_id, app=catalog, defaults={"state": "Active"})
        if row.entity.entity_type_id:
            EntityTypeApp.objects.get_or_create(entity_type_id=row.entity.entity_type_id, app=catalog,
                                                defaults={"state": "Active"})



